// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0) && caller != address(this));
        address ceoBefore = c.ceoAddress();
        // The reference owner is the deployer (address(this))
        // Only the current ceoAddress can call DrugDealer() successfully
        // If caller is not the current ceo, the call should revert
        // We test that after a successful call, ceoAddress becomes caller
        if (caller == ceoBefore) {
            vm.prank(caller);
            c.DrugDealer();
            assertTrue(c.ceoAddress() == caller);
        } else {
            vm.prank(caller);
            vm.expectRevert("Only CEO can set new address");
            c.DrugDealer();
            assertTrue(c.ceoAddress() == ceoBefore);
        }
    }
}

